import { Link, NavLink } from "react-router-dom";
import { motion } from "framer-motion";

const Navbar = () => {
  return (
    <motion.nav
      className="flex justify-between items-center px-8 py-4 bg-white shadow-md sticky top-0 z-50"
      initial={{ y: -60, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      {/* Logo */}
      <Link to="/" className="text-2xl font-bold text-indigo-700">
        AI Interview Coach
      </Link>

      {/* Links */}
      <ul className="hidden md:flex gap-8 text-gray-700 font-medium">
        <NavLink
          to="/"
          className={({ isActive }) =>
            isActive ? "text-indigo-600" : "hover:text-indigo-600"
          }
        >
          Home
        </NavLink>
        <NavLink
          to="/interview"
          className={({ isActive }) =>
            isActive ? "text-indigo-600" : "hover:text-indigo-600"
          }
        >
          Interview
        </NavLink>
        <NavLink
          to="/feedback"
          className={({ isActive }) =>
            isActive ? "text-indigo-600" : "hover:text-indigo-600"
          }
        >
          Feedback
        </NavLink>
      </ul>

      {/* Auth Buttons */}
      <div className="hidden md:flex gap-4">
        <Link
          to="/login"
          className="px-4 py-2 border border-indigo-600 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all duration-300"
        >
          Login
        </Link>
        <Link
          to="/signup"
          className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all duration-300"
        >
          Sign Up
        </Link>
      </div>
    </motion.nav>
  );
};

export default Navbar;
